import{_ as e,c as t,a2 as r,o as p}from"./chunks/framework.BQmytedh.js";const h=JSON.parse('{"title":"给所有迷茫的人们 - 王阳明参透了混沌人生的终极玩法","description":"","frontmatter":{},"headers":[],"relativePath":"哲思_人文_社科/博主_频道/岱川博士/善护念.md","filePath":"哲思_人文_社科/博主_频道/岱川博士/善护念.md","lastUpdated":1734369888000}'),o={name:"哲思_人文_社科/博主_频道/岱川博士/善护念.md"};function i(n,a,s,l,_,d){return p(),t("div",null,a[0]||(a[0]=[r('<h1 id="给所有迷茫的人们-王阳明参透了混沌人生的终极玩法" tabindex="-1">给所有迷茫的人们 - 王阳明参透了混沌人生的终极玩法 <a class="header-anchor" href="#给所有迷茫的人们-王阳明参透了混沌人生的终极玩法" aria-label="Permalink to &quot;给所有迷茫的人们 - 王阳明参透了混沌人生的终极玩法&quot;">​</a></h1><p><a href="https://www.bilibili.com/video/BV1wZ421p7y6" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1wZ421p7y6</a></p><p>&quot;善护念&quot;: 任何时间都尽量让自己的念想保持积极, 自信, 富有同情心.</p><h2 id="热评" tabindex="-1">热评 <a class="header-anchor" href="#热评" aria-label="Permalink to &quot;热评&quot;">​</a></h2><p>五月雨719:</p><p>纠正一点，王阳明知行合一讲的并不是内心知道而驱动行为，这叫做程朱理学。</p><p>王阳明讲的是知和行是统一的，不分先后。</p><p>比如我们知道要孝顺父母，不是因为知道要孝顺父母这个道理才在天凉时去给他们添衣，在酷暑时为他们纳凉，而是我心里生命情感的驱动力让我自然而然这么做的。</p><p>再比如遇到一小孩子快要饿死了，你的恻隐之心也就是生命情感推动你去帮助他，这是一气呵成的，但是你转念一想害怕被讹，于是选择了离开，那么痛苦就来了，因为你的行为和你的良知不统一。</p><p>回归到乐观心态，不是因为我知道人要乐观我才在面对痛苦时去苦笑去强迫自己淡然，而是心里本来就抱着游戏人生一切看淡的态度，那样自然而然我反映出来的行为就不会是偏激和不合适的，也就是所谓的心即理。</p><p><strong>所以人啊，不要当浮萍，一个雨天，一句恶意，一次不公平的决定… 当外界的随便一个刺激就能让你内心掀起波澜，那么还谈何幸福。</strong></p><p>而是要修炼自己的内心，感悟自己的道理，坚定自己的内心，像风一样去往该去往的地方，沿途携带上愿意追随的羽毛。</p>',12)]))}const m=e(o,[["render",i]]);export{h as __pageData,m as default};
